'use strict';
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const directory = path.resolve('learning', 'S027');
const hash = (bytes) => crypto.createHash('sha256').update(bytes).digest('hex');
function inventory(base) {
  return fs.readdirSync(base, { withFileTypes: true }).sort((a,b) => a.name.localeCompare(b.name)).flatMap((entry) => {
    const absolute = path.join(base, entry.name);
    return entry.isDirectory() ? inventory(absolute) : [{ path: path.relative(directory, absolute), sha256: hash(fs.readFileSync(absolute)) }];
  });
}
const before = inventory(directory);
const env = { ...process.env };
delete env.CAPTURE_BROWSER_EVIDENCE;
const argv = ['--test', '--test-concurrency=1', '--test-reporter=tap', ...['probe', 'syntax', 'integrity', 'browser'].map((name) => path.join('learning','S027','tests',`${name}.test.cjs`))];
const run = spawnSync(process.execPath, argv, { env, encoding: null, maxBuffer: 8 * 1024 * 1024 });
process.stdout.write(run.stdout || Buffer.alloc(0));
process.stderr.write(run.stderr || Buffer.alloc(0));
assert.equal(run.error, undefined);
assert.equal(run.status, 0);
const after = inventory(directory);
assert.deepEqual(after, before, 'Ordinary verification must not modify lesson source or historical proof.');
console.log('READ_ONLY_PROOF_INVARIANT ' + JSON.stringify({ captureUnsetInTestProcess: true, unchangedFiles: before.length, beforeSha256: hash(Buffer.from(JSON.stringify(before))), afterSha256: hash(Buffer.from(JSON.stringify(after))), exitCode: run.status, commandArgv: argv }));
